     *     declaration
     */
    private boolean isConstructorOrEnumDeclaration(Node n, Node parent) {
      JSDocInfo info;
      int valueNodeType;
      switch (parent.getType()) {
        case Token.ASSIGN:
          info = parent.getJSDocInfo();
          valueNodeType = n.getNext().getType();
          break;
