    if (currentMarker != null) {
      currentMarker.type = new JSDocInfo.TypePosition();
      currentMarker.type.setItem(typeNode);
      currentMarker.type.hasBrackets = hasLC;
      currentMarker.type.setPositionInformation(lineno, startCharno,
                                                lineno, endCharno);
    }
  }

